package tui

/*
Muestra los iconos de la fuente nerdfont, la versión de nerdfont es la v3.4.0
para ver la lista de los iconos disponibles, visita la página de la fuente nerdfont:
https://www.nerdfonts.com/cheat-sheet, solo es eliminar el prefijo `nf-` de los nombres
de los iconos y pasarlos a PascalCase:

nf-md-tune_vertical_variant -> MdTuneVerticalVariant
*/

var enableNF bool = true

func DisableNF() {
	enableNF = false
}

// Nerdfont retorna un string con el icono de la fuente nerdfont asociado al nombre
func Nerdfont(name string, cdef ...string) string {
	if f, ok := fontMap[name]; ok {
		if enableNF {
			return f
		} else if len(cdef) > 0 {
			return cdef[1]
		}
	}

	return ""
}

